package com.personal.assistant.module.tradingreview.service;
import com.personal.assistant.module.tradingreview.dto.*;import org.springframework.stereotype.Component;import java.math.*;import java.util.*;
@Component public class SentimentRuleEngine{public static final String VERSION="MVP-1.0";public SentimentResult evaluate(MarketSnapshot m){if(m.risingCount()==null||m.fallingCount()==null||m.limitUpCount()==null||m.limitDownCount()==null||m.brokenBoardRate()==null||m.maxStreak()==null||m.shanghaiChange()==null||m.turnoverAmount()==null)return new SentimentResult(null,"数据不完整",null,"关键行情指标缺失，请手工补充后重新计算。",VERSION,"{}","INCOMPLETE");BigDecimal breadth=clamp(BigDecimal.valueOf(50+50.0*(m.risingCount()-m.fallingCount())/Math.max(1,m.risingCount()+m.fallingCount())));BigDecimal board=clamp(BigDecimal.valueOf(50+m.limitUpCount()*1.2-m.limitDownCount()*2.0).subtract(m.brokenBoardRate().multiply(BigDecimal.valueOf(.5))));BigDecimal streak=clamp(BigDecimal.valueOf(m.maxStreak()*12.5));BigDecimal index=clamp(BigDecimal.valueOf(50).add(m.shanghaiChange().multiply(BigDecimal.TEN)).add(m.turnoverChange()==null?BigDecimal.ZERO:m.turnoverChange().multiply(BigDecimal.valueOf(.5))));BigDecimal score=breadth.multiply(new BigDecimal("0.25")).add(board.multiply(new BigDecimal("0.30"))).add(streak.multiply(new BigDecimal("0.25"))).add(index.multiply(new BigDecimal("0.20"))).setScale(2,RoundingMode.HALF_UP);String stage=score.compareTo(BigDecimal.valueOf(75))>=0?"上升":score.compareTo(BigDecimal.valueOf(50))>=0?"震荡":score.compareTo(BigDecimal.valueOf(30))>=0?"退潮":"冰点";BigDecimal pos=stage.equals("上升")?BigDecimal.valueOf(70):stage.equals("震荡")?BigDecimal.valueOf(40):stage.equals("退潮")?BigDecimal.valueOf(20):BigDecimal.valueOf(10);String dims="{\"breadth\":"+breadth+",\"board\":"+board+",\"streak\":"+streak+",\"indexTurnover\":"+index+"}";return new SentimentResult(score,stage,pos,"市场处于"+stage+"阶段，建议仓位不高于"+pos+"%。",VERSION,dims,"COMPLETE");}private BigDecimal clamp(BigDecimal v){return v.max(BigDecimal.ZERO).min(BigDecimal.valueOf(100)).setScale(2,RoundingMode.HALF_UP);}}